def transform(grid):
    from collections import Counter
    g = [list(r) for r in grid]; H = len(g); W = len(g[0])
    bg = Counter(v for r in g for v in r).most_common(1)[0][0]
    transposed = False

    def runs(cells):
        out = []; cur = None
        for i, v in cells:
            if v != bg:
                if cur and cur[1] == i - 1: cur = (cur[0], i)
                else:
                    if cur: out.append(cur)
                    cur = (i, i)
            else:
                if cur: out.append(cur); cur = None
        if cur: out.append(cur)
        return out

    def get_lr():
        Lr = runs([(r, g[r][0]) for r in range(H)])
        Rr = runs([(r, g[r][W-1]) for r in range(H)])
        return Lr, Rr

    Lr, Rr = get_lr()
    if not (len(Lr) == 1 and len(Rr) == 1):
        g = [list(x) for x in zip(*g)]; H, W = W, H; transposed = True
        Lr, Rr = get_lr()
    L, R = Lr[0], Rr[0]
    markers = [(r, c) for r in range(1, H-1) for c in range(1, W-1) if g[r][c] != bg]
    inL = sum(1 for r, c in markers if L[0] <= r <= L[1])
    inR = sum(1 for r, c in markers if R[0] <= r <= R[1])
    if inL >= inR:
        P, S, colP = L, R, 0
    else:
        P, S, colP = R, L, W - 1
    off = S[0] - P[0]
    rowcolor = {}
    for r, c in markers:
        v = g[r][c]; rowcolor.setdefault(r, v)
        if colP == 0:
            for cc in range(1, c): g[r][cc] = v
        else:
            for cc in range(c + 1, W - 1): g[r][cc] = v
        g[r][c] = 4
    stripe = {(r, 0) for r in range(L[0], L[1] + 1)} | {(r, W - 1) for r in range(R[0], R[1] + 1)}
    for r, v in rowcolor.items():
        r2 = r + off
        if 0 <= r2 < H:
            for c in range(W):
                if (r2, c) in stripe: continue
                g[r2][c] = v
    if transposed:
        g = [list(x) for x in zip(*g)]
    return g
